import{_ as n,a0 as p,w as d,s as o,I as s,x as e,a1 as t,A as l,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const z=JSON.parse('{"title":"zip 命令的解釋與示例 | LCTT x X-CMD","titleTemplate":false,"description":"zip 命令的解釋與示例 | LCTT (202302) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"zip 命令的解釋與示例 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"zip 命令的解釋與示例 | LCTT (202302) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202302/20230117.0 ⭐️⭐️ Learn zip Command in Linux Using Examples","title":"zip 命令的解釋與示例","tag":"202302","desc":""},"relativePath":"202302/20230117.0 ⭐️⭐️ Learn zip Command in Linux Using Examples.md","filePath":"[post].md"}'),h={name:"202302/20230117.0 ⭐️⭐️ Learn zip Command in Linux Using Examples.md"};function g(u,i,c,k,b,f){const a=p("Link");return d(),o("div",null,[i[21]||(i[21]=s("h1",{id:"zip-命令的解釋與示例",tabindex:"-1"},[e("zip 命令的解釋與示例 "),s("a",{class:"header-anchor",href:"#zip-命令的解釋與示例","aria-label":"Permalink to “zip 命令的解釋與示例”"},"​")],-1)),i[22]||(i[22]=s("blockquote",null,[s("p",null,"這是一份關於理解 Linux 中的 zip 命令的初學者指南，並附有一些例子。")],-1)),i[23]||(i[23]=s("p",null,[s("img",{src:"https://www.debugpoint.com/wp-content/uploads/2023/01/zip-file-head.jpg",alt:""})],-1)),s("p",null,[i[1]||(i[1]=e("這篇文章是 ",-1)),t(a,{href:"https://www.debugpoint.com/category/linux-commands"},{default:l(()=>[...i[0]||(i[0]=[e("Linux 命令",-1)])]),_:1}),i[2]||(i[2]=e("學習系列的一部分。",-1))]),i[24]||(i[24]=r(`<p>zip 文件是一個包含一個或多個文件的壓縮檔案。它作為一種無損數據壓縮技術被廣泛使用。由於壓縮，它佔用的磁盤空間更少，在計算機網絡上傳輸時需要的數據也更少。</p><p>這些壓縮文件可以在 Linux、Windows 和 macOS 中輕鬆提取。有各種支持壓縮 zip 文件的軟件，也提供提取它們的功能。</p><p>由於它很流行，幾乎所有的操作系統都內置了這個功能。</p><p>在本教程中，我們將談論幾種基於終端的方法來壓縮 Linux 中的文件。</p><h3 id="linux-中的-zip-命令示例" tabindex="-1">Linux 中的 Zip 命令示例 <a class="header-anchor" href="#linux-中的-zip-命令示例" aria-label="Permalink to “Linux 中的 Zip 命令示例”">​</a></h3><h4 id="語法" tabindex="-1">語法 <a class="header-anchor" href="#語法" aria-label="Permalink to “語法”">​</a></h4><p>在 Linux 中，你需要使用的壓縮文件的程序名稱是 <code>zip</code>。下面是基本的語法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>zip [壓縮文件名] file1 file2 file3</span></span></code></pre></div><p>以下是正式的語法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>zip [-options] [-b path] [-t mmddyyyy] [-n suffixes] [zipfile list] [-xi list]</span></span></code></pre></div><p>理想情況下，<code>zip</code> 命令應該被安裝在所有主流的 Linux 發行版中。如果沒有，使用下面的命令來安裝它。</p><h4 id="在-debian、ubuntu-和相關發行版上安裝" tabindex="-1">在 Debian、Ubuntu 和相關發行版上安裝 <a class="header-anchor" href="#在-debian、ubuntu-和相關發行版上安裝" aria-label="Permalink to “在 Debian、Ubuntu 和相關發行版上安裝”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install zip</span></span></code></pre></div><h4 id="在-fedora、基於-rhel-的系統上安裝" tabindex="-1">在 Fedora、基於 RHEL 的系統上安裝 <a class="header-anchor" href="#在-fedora、基於-rhel-的系統上安裝" aria-label="Permalink to “在 Fedora、基於 RHEL 的系統上安裝”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install zip</span></span></code></pre></div><h4 id="在-arch-linux-上安裝" tabindex="-1">在 Arch Linux 上安裝 <a class="header-anchor" href="#在-arch-linux-上安裝" aria-label="Permalink to “在 Arch Linux 上安裝”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pacman -S zip</span></span></code></pre></div><p>讓我們繼續看一些例子。</p><h4 id="如何壓縮文件和文件夾" tabindex="-1">如何壓縮文件和文件夾 <a class="header-anchor" href="#如何壓縮文件和文件夾" aria-label="Permalink to “如何壓縮文件和文件夾”">​</a></h4><p>我的測試目錄中有以下三個文件。它們是 <code>file1.txt</code>、<code>file2.txt</code> 和 <code>file3.txt</code>。如果我想用 zip 壓縮三個文件，並創建一個 <code>myfiles.zip</code> 的壓縮包，用下面的命令就可以了。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>zip myfiles.zip file1.txt file2.txt file3.mp3</span></span></code></pre></div><p>輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>adding: file1.txt (stored 0%)</span></span>
<span class="line"><span>adding: file2.txt (stored 0%)</span></span>
<span class="line"><span>adding: file3.mp3 (deflated 13%)</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/01/Output-of-Basic-zip-command-in-Linux.jpg" alt="Linux 中基本壓縮命令的輸出"></p><p>這裏你應該記住幾個要點。</p><ul><li>當創建一個 zip 文件時，你應該有對當前目錄的修改權限。</li><li>zip 文件格式不包含權限，即讀（4）、寫（2），和執行（1）。所以，創建該文件的用户成為該文件的所有者。</li><li>如果你想使用帶有權限的 zip，可以嘗試使用 <code>tar</code> 命令（將在後面的教程中解釋）。</li><li>在上面的輸出中，<code>zip</code> 命令顯示了被添加到存檔中的文件名和壓縮方法。</li><li>在目標文件名中指定 .zip 文件名的擴展名並不是必須的。如果你省略了 .zip，<code>zip</code> 會在最後加上 .zip。</li></ul><p>當你操作成百上千的文件時，為了減少終端中的輸出，你可以使用 <code>-q</code> 參數來抑制 <code>zip</code> 命令中的輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>zip -q myfiles.zip file1.txt file2.txt file3.txt</span></span></code></pre></div><h4 id="遞歸壓縮子文件夾" tabindex="-1">遞歸壓縮子文件夾 <a class="header-anchor" href="#遞歸壓縮子文件夾" aria-label="Permalink to “遞歸壓縮子文件夾”">​</a></h4><p><code>zip</code> 命令的 <code>-r</code> 選項使你能夠囊括所有子目錄。這個選項會遞歸地遍歷到一個目錄結構的最後一個子目錄，並將它們全部加入到壓縮文件中。</p><p>下面的命令創建了一個包含 <code>my_folder</code> 內所有內容和子目錄的壓縮文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>zip -r myfolder.zip my_folder</span></span></code></pre></div><p>你也可以使用通配符（<code>*</code>）在你的壓縮文件中包含特定類型的文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>zip -0 my_movies.zip *.mp4</span></span></code></pre></div><h4 id="混合添加文件和目錄到壓縮文件" tabindex="-1">混合添加文件和目錄到壓縮文件 <a class="header-anchor" href="#混合添加文件和目錄到壓縮文件" aria-label="Permalink to “混合添加文件和目錄到壓縮文件”">​</a></h4><p>有了以上所有的選項，<code>zip</code> 命令允許你把文件和目錄一起作為參數指定。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>zip -r myfiles.zip file1.txt file2.txt file3.txt my_folder1 my_folder2</span></span></code></pre></div><h3 id="壓縮算法" tabindex="-1">壓縮算法 <a class="header-anchor" href="#壓縮算法" aria-label="Permalink to “壓縮算法”">​</a></h3><p>zip 壓縮的默認輸出包含兩個不同的詞，即 <code>deflate</code> 和 <code>store</code>。zip 默認使用的壓縮方法是 <code>deflate</code>。如果它成功地壓縮了文件，那麼輸出顯示 <code>deflate</code>。而當它不能壓縮一個文件時，它只是將它們原封不動地存儲在 .zip 文件中。這些文件的輸出顯示為 <code>store</code>。</p><p>目前有許多壓縮算法。其中一種是 bzip2 壓縮法，在 Linux 中的 <code>zip</code> 命令支持它。你可以指定壓縮算法作為一個命令選項來使用。使用選項 <code>-Z</code>，後面跟上算法名稱，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>zip -r -Z bzip2 myfolder.zip my_folder</span></span></code></pre></div><h4 id="壓縮級別" tabindex="-1">壓縮級別 <a class="header-anchor" href="#壓縮級別" aria-label="Permalink to “壓縮級別”">​</a></h4><p><code>zip</code> 命令還允許你指定壓縮級別。壓縮級別是指你想讓 zip 優化多少來減少包的大小。它是一個從 0 到 9 的數值範圍。壓縮級別為 9 的值是最高的壓縮。默認值是 6。</p><p>記住，如果你用 zip 壓縮成千上萬個大小不一的文件，它可能會佔用較多的系統資源，並花費大量的時間。所以，如果你在程序中使用它，或者用 shell 腳本處理大量的文件，請遵循正確的編程標準。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>zip -9 -r myfolder.zip my_folder</span></span></code></pre></div><h4 id="用密碼保護一個壓縮文件" tabindex="-1">用密碼保護一個壓縮文件 <a class="header-anchor" href="#用密碼保護一個壓縮文件" aria-label="Permalink to “用密碼保護一個壓縮文件”">​</a></h4><p>你也可以用下面的 <code>-e</code> 選項對壓縮文件進行密碼保護：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>zip -e -r myfolder.zip my_folder</span></span></code></pre></div><p>運行該命令後，它將要求輸入密碼。</p><blockquote><p>注意。儘量不要使用 zip 命令來對壓縮文件進行密碼保護。zip 的加密算法是使用流式加密的 PKZIP。而它很容易被破解。如果你想保護你的文件，請使用 7-Zip 或其他高級工具。</p></blockquote><h4 id="分割較大的壓縮文件" tabindex="-1">分割較大的壓縮文件 <a class="header-anchor" href="#分割較大的壓縮文件" aria-label="Permalink to “分割較大的壓縮文件”">​</a></h4><p>許多應用程序、服務器和文件共享可能包含固定大小的文件上傳限制。例如，你有一個 10GB 的文件，但服務只允許每個文件 1GB。使用 <code>zip</code> 的 <code>-s</code> 選項，你可以將其壓縮並分割成幾塊進行上傳。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>zip -s 1g -r myfolder.zip my_folder</span></span></code></pre></div><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>你學到了一些 <code>zip</code> 命令的基本知識。它對大多數本地情況很有用，在這些情況下，你需要通過即時壓縮來進行快速備份。然而，對於更高級的選項，你應該使用 7-Zip 或其他命令，我將在接下來的幾篇文章中分享。</p>`,55)),s("p",null,[i[4]||(i[4]=e("同時，你可以在 ",-1)),t(a,{href:"https://linux.die.net/man/1/zip"},{default:l(()=>[...i[3]||(i[3]=[e("zip 手冊",-1)])]),_:1}),i[5]||(i[5]=e(" 中瞭解更多。",-1))]),i[25]||(i[25]=s("hr",null,null,-1)),s("p",null,[i[7]||(i[7]=e("via: ",-1)),t(a,{href:"https://www.debugpoint.com/zip-command-linux-examples/"},{default:l(()=>[...i[6]||(i[6]=[e("https://www.debugpoint.com/zip-command-linux-examples/",-1)])]),_:1})]),s("p",null,[i[12]||(i[12]=e("作者：",-1)),t(a,{href:"https://www.debugpoint.com/author/admin1/"},{default:l(()=>[...i[8]||(i[8]=[e("Arindam",-1)])]),_:1}),i[13]||(i[13]=e(" 選題：",-1)),t(a,{href:"https://github.com/lkxed"},{default:l(()=>[...i[9]||(i[9]=[e("lkxed",-1)])]),_:1}),i[14]||(i[14]=e(" 譯者：",-1)),t(a,{href:"https://github.com/Chao-zhi"},{default:l(()=>[...i[10]||(i[10]=[e("Chao-zhi",-1)])]),_:1}),i[15]||(i[15]=e(" 校對：",-1)),t(a,{href:"https://github.com/wxy"},{default:l(()=>[...i[11]||(i[11]=[e("wxy",-1)])]),_:1})]),s("p",null,[i[18]||(i[18]=e("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...i[16]||(i[16]=[e("LCTT",-1)])]),_:1}),i[19]||(i[19]=e(" 原創編譯，",-1)),t(a,{href:"https://linux.cn/"},{default:l(()=>[...i[17]||(i[17]=[e("Linux中國",-1)])]),_:1}),i[20]||(i[20]=e(" 榮譽推出",-1))])])}const y=n(h,[["render",g]]);export{z as __pageData,y as default};
